mapper.select:
select ur.id, ur.user_id, u1.username, ur.reported_user_id as reportedUserId, u2.username as reportedUsername, ur.report_time, ur.report_reason, ur.status, ur.reviewer_id, a.name as reviewer_name, ur.review_time, ur.review_result, ur.review_reason from user_report ur left join user u1 on ur.user_id = u1.id left join user u2 on ur.reported_user_id = u2.id left join admin a on ur.reviewer_id = a.id
and ur.status = #{status}
and ur.user_id = #{userId}
and ur.reported_user_id = #{reportedUserId}
and ur.reviewer_id = #{reviewerId}
order by ur.report_time desc
